",paid:\"money in\",artwork_in:\"paid + logo received\",artwork_built:\"720x160 slide ready\",\n    sent_to_dean:\"emailed to the school\",complete:\"paid + loaded\"};\n  const money = n => \"$\" + (n||0).toLocaleString();\n  const d10 = s => (s||\"\").slice(0,10);\n  const esc = s => String(s==null?\"\":s).replace(/[&<>\"]/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\n  const f = D.funnel, leads = D.leads;\n  const paidN = f.reached.paid, goalN = 15;\n  const deadline = new Date(\"2026-11-20T23:59:00-05:00\"), days = Math.max(0, Math.ceil((deadline - new Date())/86400000));\n\n  document.getElementById('meta').textContent = \"Updated \" + (D.built_at||\"\").replace(\"T\",\" \").slice(0,16) + \" \u00b7 \" + leads.length + \" businesses emailed Fri Oct 23 \u00b7 load deadline Fri Nov 20\";\n  document.getElementById('sheetlink').href = D.sheet_url || \"#\";\n\n  const kp = [\n    {lbl:\"Paid\", num:paidN, cls:\"score\", sub:money(f.money.paid)+\" of \"+money(goalN*400)+\" goal \u00b7 \"+goalN+\" ads\", bar:paidN/goalN},\n    {lbl:\"Committed, not paid\", num:f.at_stage.committed, sub:money(f.money.committed_unpaid)+\" to collect\"},\n    {lbl:\"Drafts waiting on you\", num:f.drafts_waiting, sub:\"open Gmail Drafts, read, send\"},\n    {lbl:\"Days to load deadline\", num:days, sub:\"opening night Tue Dec 1\"},\n    {lbl:\"Replied\", num:f.reached.replied, sub:f.at_stage.bounced+\" bounced \u00b7 \"+(leads.length-f.reached.replied-f.at_stage.bounced)+\" quiet\"}\n  ];\n  document.getElementById('kpis').innerHTML = kp.map(k => `<div class=\"kpi\"><div class=\"lbl\">${k.lbl}</div><div class=\"num ${k.cls||\"\"}\">${k.num}</div><div class=\"sub\">${k.sub}</div>${k.bar!=null?`<div class=\"goal\"><i style=\"width:${Math.min(100,k.bar*100)}%\"></i></div>`:\"\"}</div>`).join(\"\");\n\n  // Your move: drafts waiting + Tommy-owned actions\n  const moves = [];\n  leads.forEach(l => {\n    if (l.drafts.length) moves.push(`<li><span class=\"dot t\"></span>${esc(l.company)}: send the waiting draft${l.drafts.length>1?\"s (\"+l.drafts.length+\")\":\"\"} <a href=\"${l.drafts[0]}\" target=\"_blank\" rel=\"noopener\">open</a><span class=\"who\">you</span></li>`);\n    else if (l.next_owner === \"Tommy\") moves.push(`<li><span class=\"dot t\"></span>${esc(l.company)}: ${esc(l.next_action)} <a href=\"${l.gmail}\" target=\"_blank\" rel=\"noopener\">thread</a><span class=\"who\">you</span></li>`);\n  });\n  if (D.other_drafts) moves.push(`<li><span class=\"dot t\"></span>${D.other_drafts} draft(s) to Brad / Angie / Dean in <a href=\"https://mail.google.com/mail/u/0/#drafts\" target=\"_blank\" rel=\"noopener\">Gmail Drafts</a><span class=\"who\">you</span></li>`);\n  leads.forEach(l => { if (l.next_owner === \"Claude\") moves.push(`<li><span class=\"dot c\"></span>${esc(l.company)}: ${esc(l.next_action)}<span class=\"who\">Claude drafts it</span></li>`); });\n  document.getElementById('move').innerHTML = moves.length ? moves.join(\"\") : \"<li>Nothing waiting on you.</li>\";\n\n  // Sent vs drafted\n  const sl = D.sent_log || [];\n  const cnt = k => sl.filter(e => e.kind===k).length;\n  document.getElementById('sv').innerHTML = [[\"Sent as drafted\",cnt(\"sent_as_drafted\")],[\"Edited\",cnt(\"edited\")],[\"Rewritten\",cnt(\"rewritten\")]]\n    .map(([l,n]) => `<div><div class=\"n\">${n}</div><div class=\"l\">${l}</div></div>`).join(\"\");\n  document.getElementById('svlist').innerHTML = sl.slice(0,6).map(e => `${esc((e.at||\"\").slice(5,16).replace(\"T\",\" \"))} \u00b7 ${esc(e.company)} \u00b7 ${esc(e.kind.replace(/_/g,\" \"))}${e.similarity!=null?\" (\"+Math.round(e.similarity*100)+\"% alike)\":\"\"}`).join(\"<br>\") + (sl.length? \"\" : \"No sends matched yet.\");\n\n  // Funnel\n  const maxR = f.reached.sent || 1;\n  let filter = \"all\";\n  const fun = document.getElementById('funnel');\n  fun.innerHTML = STAGES.map(s => {\n    const r = f.reached[s]||0, a = f.at_stage[s]||0;\n    return `<div class=\"stage\" role=\"button\" tabindex=\"0\" data-stage=\"${s}\" aria-pressed=\"false\">\n      <div class=\"nm\">${LABEL[s]}<small>${HINT[s]}</small></div>\n      <div class=\"bar\"><i class=\"${s==='paid'||s==='artwork_in'||s==='artwork_built'||s==='sent_to_dean'||s==='complete'?'paidbar':''}\" style=\"width:${Math.max(1,(r/maxR)*100)}%\"></i></div>\n      <div class=\"ct\" title=\"${r} reached this stage or further; ${a} sit here now\">${a}<span class=\"small\"> / ${r}</span></div></div>`;\n  }).join(\"\");\n  const chips = document.getElementById('chips');\n  chips.innerHTML = `<button class=\"chip\" data-stage=\"all\" aria-pressed=\"true\">All ${leads.length}</button>` +\n    `<button class=\"chip\" data-stage=\"unpaid\" aria-pressed=\"false\">Committed, not paid ${f.at_stage.committed}</button>` +\n    `<button class=\"chip\" data-stage=\"tommy\" aria-pressed=\"false\">Needs you</button>` +\n    SIDE.map(s => `<button class=\"chip\" data-stage=\"${s}\" aria-pressed=\"false\">${LABEL[s]} ${f.at_stage[s]||0}</button>`).join(\"\");\n\n  function setFilter(s){\n    filter = s;\n    document.querySelectorAll('[data-stage]').forEach(el => el.setAttribute('aria-pressed', el.dataset.stage===s ? \"true\":\"false\"));\n    render();\n  }\n  document.querySelectorAll('[data-stage]').forEach(el => {\n    el.addEventListener('click', () => setFilter(el.dataset.stage));\n    el.addEventListener('keydown', e => { if (e.key===\"Enter\"||e.key===\" \") { e.preventDefault(); setFilter(el.dataset.stage); } });\n  });\n\n  // Board\n  const q = document.getElementById('q');\n  q.addEventListener('input', render);\n  const order = {}; STAGES.slice().reverse().concat(SIDE).forEach((s,i) => order[s]=i);\n  function matches(l){\n    if (filter===\"unpaid\") return l.committed && !l.paid;\n    if (filter===\"tommy\") return l.next_owner===\"Tommy\" || l.drafts.length;\n    if (filter!==\"all\" && l.stage!==filter) return false;\n    const t = q.value.trim().toLowerCase();\n    if (!t) return true;\n    return [l.company,l.first_name,l.team,l.notes,l.last_inbound_summary,l.next_action,l.segment].join(\" \").toLowerCase().includes(t);\n  }\n  let selected = null;\n  function render(){\n    const rows = leads.filter(matches).sort((a,b) => (order[a.stage]??99)-(order[b.stage]??99) || a.company.localeCompare(b.company));\n    document.getElementById('boardtitle').textContent = (filter===\"all\"?\"All businesses\":filter===\"unpaid\"?\"Committed, not paid\":filter===\"tommy\"?\"Needs you\":LABEL[filter]) + \" \u00b7 \" + rows.length;\n    document.getElementById('rows').innerHTML = rows.map(l => `<tr class=\"row\" tabindex=\"0\" data-email=\"${esc(l.email)}\" aria-selected=\"${selected===l.email}\">\n      <td><b>${esc(l.company)}</b>${l.first_name?`<div class=\"small\">${esc(l.first_name)}</div>`:\"\"}</td>\n      <td><span class=\"pill ${l.stage}\">${LABEL[l.stage]||l.stage}</span></td>\n      <td class=\"flag\">${l.paid?\"<b>PAID</b> \"+d10(l.paid_at):(l.committed?\"committed\":\"\")}</td>\n      <td class=\"money\">${(l.committed||l.paid)?money(l.amount):\"\"}</td>\n      <td>${esc(l.team)}</td>\n      <td class=\"small\" title=\"${esc(l.last_inbound_summary)}\">${esc(l.last_inbound_summary)}${l.last_inbound_at?`<div>${d10(l.last_inbound_at)}</div>`:\"\"}</td>\n      <td class=\"small\">${esc(l.next_action)}${l.next_owner?` <span class=\"who\" style=\"color:var(--muted)\">\u00b7 ${esc(l.next_owner)}</span>`:\"\"}</td>\n      <td>${l.drafts.length?`<a href=\"${l.drafts[0]}\" target=\"_blank\" rel=\"noopener\">${l.drafts.length} waiting</a>`:\"\"}</td>\n      <td><a href=\"${l.gmail}\" target=\"_blank\" rel=\"noopener\">open</a></td></tr>`).join(\"\") || `<tr><td colspan=\"9\" class=\"small\">No businesses match.</td></tr>`;\n    document.querySelectorAll('tr.row').forEach(tr => {\n      tr.addEventListener('click', e => { if (e.target.tagName!==\"A\") openDrawer(tr.dataset.email); });\n      tr.addEventListener('keydown', e => { if (e.key===\"Enter\") openDrawer(tr.dataset.email); });\n    });\n  }\n  const drawer = document.getElementById('drawer');\n  function openDrawer(email){\n    const l = leads.find(x => x.email===email); if (!l) return;\n    selected = email;\n    const row = (k,v) => v ? `<dt>${k}</dt><dd>${v}</dd>` : \"\";\n    drawer.innerHTML = `<button class=\"close\" id=\"close\">Close</button><h3>${esc(l.company)}</h3>\n      <div class=\"small\">${esc(l.first_name||\"\")} ${esc(l.email)} \u00b7 ${esc(l.segment.replace(/_/g,\" \"))}</div>\n      <p><span class=\"pill ${l.stage}\">${LABEL[l.stage]||l.stage}</span> ${l.paid?'<span class=\"pill paid\">PAID '+money(l.amount)+'</span>':(l.committed?'<span class=\"pill committed\">committed '+money(l.amount)+'</span>':\"\")}</p>\n      <dl class=\"kv\">\n        ${row(\"Opener sent\", d10(l.step1_sent_at))}${row(\"Follow-ups\", l.followups)}\n        ${row(\"Last from them\", d10(l.last_inbound_at))}${row(\"Last from Tom\", d10(l.last_outbound_at))}\n        ${row(\"Team\", esc(l.team))}${row(\"Payment\", esc(l.paid_method))}${row(\"Paid on\", d10(l.paid_at))}\n        ${row(\"Artwork in\", d10(l.artwork_received_at) + (l.artwork_files.length?\" \u00b7 \"+l.artwork_files.map(esc).join(\", \"):\"\"))}\n        ${row(\"Artwork built\", d10(l.artwork_built_at))}${row(\"Sent to Dean\", d10(l.sent_to_dean_at))}\n        ${row(\"Next action\", esc(l.next_action) + (l.next_owner?\" (\"+esc(l.next_owner)+\")\":\"\"))}\n        ${row(\"Notes\", esc(l.notes))}\n      </dl>\n      ${l.last_inbound_summary?`<div class=\"quote\"><b>Their last message:</b> ${esc(l.last_inbound_summary)}</div>`:\"\"}\n      <p>${l.drafts.map((d,i) => `<a href=\"${d}\" target=\"_blank\" rel=\"noopener\">Draft ${i+1} waiting</a>`).join(\" \u00b7 \")}${l.drafts.length?\" \u00b7 \":\"\"}<a href=\"${l.gmail}\" target=\"_blank\" rel=\"noopener\">Open the Gmail thread</a></p>`;\n    drawer.hidden = false;\n    document.getElementById('close').addEventListener('click', () => { drawer.hidden = true; selected = null; render(); });\n    render();\n  }\n  render();\n})();\n<\/script>\n\n</body>\n</html>\n";

function denied(res) {
  res.setHeader("WWW-Authenticate", 'Basic realm="RHS Boosters", charset="UTF-8"');
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Robots-Tag", "noindex, nofollow");
  res.status(401).send("Login required.");
}

function safeEqual(a, b) {
  if (typeof a !== "string" || typeof b !== "string") return false;
  const enc = new TextEncoder();
  const x = enc.encode(a), y = enc.encode(b);
  if (x.length !== y.length) return false;
  let d = 0;
  for (let i = 0; i < x.length; i++) d |= x[i] ^ y[i];
  return d === 0;
}

export default async function handler(req, res) {
  const user = process.env.BOOSTERS_USER, pass = process.env.BOOSTERS_PASS;
  if (!user || !pass) { res.status(503).send("Dashboard login is not configured."); return; }
  const h = req.headers.authorization || "";
  if (!h.startsWith("Basic ")) return denied(res);
  let decoded = "";
  try { decoded = Buffer.from(h.slice(6), "base64").toString("utf8"); } catch { return denied(res); }
  const i = decoded.indexOf(":");
  if (i < 0) return denied(res);
  const u = decoded.slice(0, i), p = decoded.slice(i + 1);
  if (!(safeEqual(u, user) && safeEqual(p, pass))) return denied(res);
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "private, no-store");
  res.setHeader("X-Robots-Tag", "noindex, nofollow");
  res.status(200).send(HTML);
}
